reply:
I used a two-column layout because the catalog has no generic container. The left column holds the four KPI tiles and the right column holds the comparison chart. The inline block shape (`type` plus the component's properties) is my assumption about how `columns` takes its blocks, so check it against your renderer.

<a2ui-json>
[
  {
    "version": "v0.9.1",
    "createSurface": {
      "surfaceId": "metrics_overview",
      "catalogId": "https://a2uicatalog.ai/catalog/c-data-display.json"
    }
  },
  {
    "version": "v0.9.1",
    "updateComponents": {
      "surfaceId": "metrics_overview",
      "components": [
        {
          "id": "root",
          "component": "columns",
          "cols": 2,
          "gap": "1.5rem",
          "align": "top",
          "items": [
            {
              "blocks": [
                {
                  "type": "heading",
                  "text": "Key metrics"
                },
                {
                  "type": "metric_row",
                  "cols": 2,
                  "metrics": [
                    {
                      "value": "482",
                      "prefix": "$",
                      "suffix": "K",
                      "label": "Monthly revenue",
                      "sub": "+8.4% vs last month",
                      "accent": "#22c55e",
                      "trend": "up"
                    },
                    {
                      "value": "28.4K",
                      "label": "Active users",
                      "sub": "+5.1% vs last month",
                      "accent": "#3b82f6",
                      "trend": "up"
                    },
                    {
                      "value": "3.8",
                      "suffix": "%",
                      "label": "Conversion rate",
                      "sub": "-0.3 pts vs last month",
                      "accent": "#eab308",
                      "trend": "down"
                    },
                    {
                      "value": "2.1",
                      "suffix": "%",
                      "label": "Churn rate",
                      "sub": "-0.4 pts vs last month",
                      "accent": "#a855f7",
                      "trend": "down"
                    }
                  ]
                }
              ]
            },
            {
              "blocks": [
                {
                  "type": "heading",
                  "text": "Revenue: this year vs last year ($K)"
                },
                {
                  "type": "chartjs_bar",
                  "labels": ["Jan", "Feb", "Mar", "Apr", "May", "Jun"],
                  "datasets": [
                    {
                      "label": "Last year",
                      "data": [310, 335, 352, 380, 401, 425]
                    },
                    {
                      "label": "This year",
                      "data": [372, 398, 421, 447, 445, 482]
                    }
                  ]
                }
              ]
            }
          ]
        }
      ]
    }
  }
]
</a2ui-json>
